 for(int id:q.layout.block_ids){q.physical_slots.push_back(int(ptr.size()));storage.emplace_back();for(double x:core.model.blocks.at(id).values)storage.back().emplace_back(x);ptr.push_back(storage.back().data());}
 J s(core.station[k]),v(core.row[k]);q.station_slot=int(ptr.size());ptr.push_back(&s);q.row_slot=int(ptr.size());ptr.push_back(&v);double max_scaled=0;
